    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def findDuplicate(self, nums: List[int]) -> int:\n        min_val = 1 # \u6240\u67e5\u627e\u6570\u5b57\u8303\u56f4\u7684\u6700\u5c0f\u503c\n        max_val = len(nums) # \u6240\u67e5\u627e\u6570\u5b57\u8303\u56f4\u7684\u6700\u5927\u503c\n\n        while min_val < max_val:\n            mid = (min_val + max_val) // 2\n            # \u8ba1\u6570\n            cnt = sum(min_val <= num <= mid for num in nums)\n\n            if cnt > mid - min_val + 1: # \u4e2a\u6570\u8d85\u51fa\u8303\u56f4\u957f\u5ea6\uff0c\u5373\u5b58\u5728\u91cd\u590d\u6570\n                max_val = mid\n            else:\n                min_val = mid + 1\n\n        return min_val\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.findDuplicate(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
