    "\u4e00\u4f4d\u8001\u5e08\u6b63\u5728\u51fa\u4e00\u573a\u7531 n\u00a0\u9053\u5224\u65ad\u9898\u6784\u6210\u7684\u8003\u8bd5\uff0c\u6bcf\u9053\u9898\u7684\u7b54\u6848\u4e3a true \uff08\u7528 'T' \u8868\u793a\uff09\u6216\u8005 false \uff08\u7528 'F'\u00a0\u8868\u793a\uff09\u3002\u8001\u5e08\u60f3\u589e\u52a0\u5b66\u751f\u5bf9\u81ea\u5df1\u505a\u51fa\u7b54\u6848\u7684\u4e0d\u786e\u5b9a\u6027\uff0c\u65b9\u6cd5\u662f\u00a0\u6700\u5927\u5316\u00a0\u6709 \u8fde\u7eed\u76f8\u540c\u00a0\u7ed3\u679c\u7684\u9898\u6570\u3002\uff08\u4e5f\u5c31\u662f\u8fde\u7eed\u51fa\u73b0 true \u6216\u8005\u8fde\u7eed\u51fa\u73b0 false\uff09\u3002\n\n\u7ed9\u4f60\u4e00\u4e2a\u5b57\u7b26\u4e32\u00a0answerKey\u00a0\uff0c\u5176\u4e2d\u00a0answerKey[i]\u00a0\u662f\u7b2c i\u00a0\u4e2a\u95ee\u9898\u7684\u6b63\u786e\u7ed3\u679c\u3002\u9664\u6b64\u4ee5\u5916\uff0c\u8fd8\u7ed9\u4f60\u4e00\u4e2a\u6574\u6570 k\u00a0\uff0c\u8868\u793a\u4f60\u80fd\u8fdb\u884c\u4ee5\u4e0b\u64cd\u4f5c\u7684\u6700\u591a\u6b21\u6570\uff1a\n\n\t\u6bcf\u6b21\u64cd\u4f5c\u4e2d\uff0c\u5c06\u95ee\u9898\u7684\u6b63\u786e\u7b54\u6848\u6539\u4e3a\u00a0'T' \u6216\u8005\u00a0'F'\u00a0\uff08\u4e5f\u5c31\u662f\u5c06 answerKey[i] \u6539\u4e3a\u00a0'T'\u00a0\u6216\u8005\u00a0'F'\u00a0\uff09\u3002\n\n\u8bf7\u4f60\u8fd4\u56de\u5728\u4e0d\u8d85\u8fc7 k\u00a0\u6b21\u64cd\u4f5c\u7684\u60c5\u51b5\u4e0b\uff0c\u6700\u5927\u00a0\u8fde\u7eed 'T'\u00a0\u6216\u8005 'F'\u00a0\u7684\u6570\u76ee\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1aanswerKey = \"TTFF\", k = 2\n\u8f93\u51fa\uff1a4\n\u89e3\u91ca\uff1a\u6211\u4eec\u53ef\u4ee5\u5c06\u4e24\u4e2a 'F' \u90fd\u53d8\u4e3a 'T' \uff0c\u5f97\u5230 answerKey = \"TTTT\" \u3002\n\u603b\u5171\u6709\u56db\u4e2a\u8fde\u7eed\u7684 'T' \u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1aanswerKey = \"TFFT\", k = 1\n\u8f93\u51fa\uff1a3\n\u89e3\u91ca\uff1a\u6211\u4eec\u53ef\u4ee5\u5c06\u6700\u524d\u9762\u7684 'T' \u6362\u6210 'F' \uff0c\u5f97\u5230 answerKey = \"FFFT\" \u3002\n\u6216\u8005\uff0c\u6211\u4eec\u53ef\u4ee5\u5c06\u7b2c\u4e8c\u4e2a 'T' \u6362\u6210 'F' \uff0c\u5f97\u5230 answerKey = \"TFFF\" \u3002\n\u4e24\u79cd\u60c5\u51b5\u4e0b\uff0c\u90fd\u6709\u4e09\u4e2a\u8fde\u7eed\u7684 'F' \u3002\n```\n\n\u793a\u4f8b 3\uff1a\n\n```\n\u8f93\u5165\uff1aanswerKey = \"TTFTTFTT\", k = 1\n\u8f93\u51fa\uff1a5\n\u89e3\u91ca\uff1a\u6211\u4eec\u53ef\u4ee5\u5c06\u7b2c\u4e00\u4e2a 'F' \u6362\u6210 'T' \uff0c\u5f97\u5230 answerKey = \"TTTTTFTT\" \u3002\n\u6216\u8005\u6211\u4eec\u53ef\u4ee5\u5c06\u7b2c\u4e8c\u4e2a 'F' \u6362\u6210 'T' \uff0c\u5f97\u5230 answerKey = \"TTFTTTTT\" \u3002\n\u4e24\u79cd\u60c5\u51b5\u4e0b\uff0c\u90fd\u6709\u4e94\u4e2a\u8fde\u7eed\u7684 'T' \u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\tn == answerKey.length\n\n\t1 <= n <= 5 * 104\n\n\tanswerKey[i]\u00a0\u8981\u4e48\u662f\u00a0'T' \uff0c\u8981\u4e48\u662f\u00a0'F'\n\n\t1 <= k <= n",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1aanswerKey\u3001k\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def maxConsecutiveAnswers(self, answerKey: str, k: int) -> int:\n        def maxConsecutiveChar(ch: str) -> int:\n            ans, left, sum = 0, 0, 0\n            for right in range(len(answerKey)):\n                sum += answerKey[right] != ch\n                while sum > k:\n                    sum -= answerKey[left] != ch\n                    left += 1\n                ans = max(ans, right - left + 1)\n            return ans\n        return max(maxConsecutiveChar('T'), maxConsecutiveChar('F'))\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.maxConsecutiveAnswers(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
